#include <catch2/catch_test_macros.hpp>

TEST_CASE("Buffer copy", "[buffer]") {
    Buffer src{"hello"};
    Buffer dst = src;
    REQUIRE(dst.size() == src.size());
    REQUIRE(dst.data() != src.data());   // deep copy
}
